package jlkvm.verify;

import static org.junit.Assert.*;
import static org.junit.Assume.assumeTrue;

import java.io.File;
import java.nio.file.Files;
import jlkvm.ClassSource;
import jlkvm.Corpus;
import jlkvm.classfile.ClassFile;
import jlkvm.classfile.ClassParser;
import org.junit.Test;

/**
 * T09: reference maps of 10 sample methods (classes generated by tests/vmspec/gen_verify_cases.sh, see
 * tests/vmspec/gen/VerifyGen.java) against tables worked out by hand from the bytecode ("javap -c" offsets).
 * Notation: L:<ref locals> S:<ref stack words> sp=<stack words>; long/double take 2 stack words and 2 local slots.
 */
public class TypeMapsTest {
    private static CorpusVerifyTest.MapSource app;
    private static TypeMaps maps;

    private static void setup() throws Exception {
        File dir = GeneratedVerifyTest.DIR;
        assumeTrue("run tests/vmspec/gen_verify_cases.sh first", new File(dir, "cases.txt").isFile());
        app = new CorpusVerifyTest.MapSource();
        for (String l : Files.readAllLines(new File(dir, "cases.txt").toPath(), java.nio.charset.StandardCharsets.UTF_8)) {
            String id = l.split("\t")[0];
            app.m.put("vf/" + id, Files.readAllBytes(new File(dir, id + ".class").toPath()));
        }
        ClassSource st = CorpusVerifyTest.stubs(true);
        maps = new TypeMaps(new Verifier(new SourceHierarchy(app, st), true, true));
    }

    private static ClassFile cls(String id) { return ClassParser.parse(app.m.get("vf/" + id)); }

    private static void check(String id, String method, Object... pcAndExpected) throws Exception {
        if (maps == null) setup();
        ClassFile cf = cls(id);
        ClassFile.MethodInfo m = null;
        for (ClassFile.MethodInfo x : cf.methods) if (x.name.equals(method)) m = x;
        assertNotNull(id + "." + method, m);
        for (int i = 0; i < pcAndExpected.length; i += 2) {
            int pc = (Integer) pcAndExpected[i];
            TypeMaps.RefMap r = maps.at(cf, m, pc);
            assertNotNull(id + " pc " + pc, r);
            assertEquals(id + " pc " + pc, pcAndExpected[i + 1], r.toString());
        }
    }

    @Test public void m01_longDoubleNoRefs() throws Exception {      // (JD)J: refs never appear, depth counts 2 per long/double
        check("p03_long_double_slots", "t",
                0, "L:- S:- sp=0", 1, "L:- S:- sp=2", 2, "L:- S:- sp=4", 3, "L:- S:- sp=4", 4, "L:- S:- sp=2",
                5, "L:- S:- sp=4", 7, "L:- S:- sp=2", 8, "L:- S:- sp=4", 9, "L:- S:- sp=1", 12, "L:- S:- sp=0",
                14, "L:- S:- sp=2", 15, "L:- S:- sp=0", 16, "L:- S:- sp=2");
    }

    @Test public void m02_uninitializedOnStack() throws Exception {  // new Object; dup; branches; invokespecial
        check("p04_uninit_new_branch", "t",
                0, "L:- S:- sp=0", 3, "L:- S:0 sp=1", 4, "L:- S:0,1 sp=2", 5, "L:- S:0,1 sp=3", 8, "L:- S:0,1 sp=2",
                9, "L:- S:0,1 sp=3", 12, "L:- S:0,1 sp=2", 13, "L:- S:0,1 sp=3", 14, "L:- S:0,1 sp=2", 17, "L:- S:0 sp=1");
    }

    @Test public void m03_uninitializedThisConstructor() throws Exception {   // <init>(I)V
        check("p05_ctor_uninit_this", "<init>",
                0, "L:0 S:- sp=0", 1, "L:0 S:0 sp=1", 2, "L:0 S:0 sp=2", 5, "L:0 S:0 sp=1", 8, "L:0 S:- sp=0");
    }

    @Test public void m04_handlerFrame() throws Exception {          // (I)I with an Exception handler at 6
        check("p06_handler", "t",
                0, "L:- S:- sp=0", 4, "L:- S:- sp=0", 5, "L:- S:- sp=1", 6, "L:- S:0 sp=1", 7, "L:- S:- sp=0", 8, "L:- S:- sp=1");
    }

    @Test public void m05_handlerCatchSuperclassFrame() throws Exception {
        check("p07_catch_all_subclass_frame", "t", 0, "L:- S:- sp=0", 1, "L:- S:- sp=1", 2, "L:- S:0 sp=1", 3, "L:- S:- sp=0");
    }

    @Test public void m06_interfaceArgumentAndCalls() throws Exception {
        check("p08_interface_as_object", "t",
                0, "L:0 S:- sp=0", 1, "L:0 S:0 sp=1", 4, "L:0 S:0 sp=1", 5, "L:0 S:0,1 sp=2", 8, "L:0 S:0 sp=1",
                9, "L:0 S:0,1 sp=2", 14, "L:0 S:0 sp=1");
        // while a call runs, the arguments belong to the callee: pc 1 invokestatic o(Object) pops its only argument
        ClassFile cf = cls("p08_interface_as_object");
        ClassFile.MethodInfo t = cf.findMethod("t", "(Ljava/lang/Runnable;)Ljava/lang/Object;");
        assertEquals("L:0 S:- sp=0", maps.atCall(cf, t, 1).toString());
        assertEquals("L:0 S:0 sp=1", maps.atCall(cf, t, 5).toString());    // [obj, arg] -> [obj]
        assertEquals("L:0 S:0 sp=1", maps.atCall(cf, t, 9).toString());    // invokeinterface run(): receiver popped
        try {
            maps.atCall(cf, t, 0);
            fail("pc 0 is not an invoke");
        } catch (IllegalArgumentException expected) {
        }
    }

    @Test public void m07_arrays() throws Exception {                // ([[String)Object, local 1 set at pc 16
        check("p09_arrays", "t",
                0, "L:0 S:- sp=0", 1, "L:0 S:0 sp=1", 2, "L:0 S:0 sp=2", 3, "L:0 S:0 sp=1", 4, "L:0 S:0 sp=2",
                5, "L:0 S:0 sp=1", 6, "L:0 S:- sp=0", 8, "L:0 S:- sp=1", 10, "L:0 S:- sp=2", 14, "L:0 S:0 sp=1",
                15, "L:0 S:0,1 sp=2", 16, "L:0 S:0 sp=1", 17, "L:0,1 S:- sp=0", 18, "L:0,1 S:0 sp=1");
    }

    @Test public void m08_nullAndMergedFrames() throws Exception {   // (I)String, null and String merge at pc 10
        check("p13_null_flows", "t",
                0, "L:- S:- sp=0", 1, "L:- S:- sp=1", 4, "L:- S:- sp=0", 5, "L:- S:0 sp=1", 8, "L:- S:- sp=0", 10, "L:- S:0 sp=1");
    }

    @Test public void m09_fieldAccess() throws Exception {           // static (p14)I: receiver, int, array reference
        check("p14_field_access", "t",
                0, "L:0 S:- sp=0", 1, "L:0 S:0 sp=1", 3, "L:0 S:0 sp=2", 6, "L:0 S:- sp=0", 7, "L:0 S:0 sp=1",
                10, "L:0 S:- sp=1", 13, "L:0 S:1 sp=2", 14, "L:0 S:- sp=2", 15, "L:0 S:- sp=1");
    }

    @Test public void m10_stackManipulationWide() throws Exception { // dup_x2 / dup2_x2 / swap keep the word depth exact
        check("p11_stack_ops_wide", "t",
                0, "L:- S:- sp=0", 1, "L:- S:- sp=2", 2, "L:- S:- sp=3", 3, "L:- S:- sp=4", 4, "L:- S:- sp=3", 5, "L:- S:- sp=1",
                6, "L:- S:- sp=3", 7, "L:- S:- sp=5", 8, "L:- S:- sp=7", 9, "L:- S:- sp=5", 10, "L:- S:- sp=3", 11, "L:- S:- sp=1",
                12, "L:- S:- sp=2", 13, "L:- S:- sp=3", 14, "L:- S:- sp=3", 15, "L:- S:- sp=2", 16, "L:- S:- sp=1");
    }

    @Test public void cacheAndEdgeCases() throws Exception {
        if (maps == null) setup();
        ClassFile cf = cls("p04_uninit_new_branch");
        ClassFile.MethodInfo t = cf.findMethod("t", "(I)Ljava/lang/Object;");
        TypeMaps.RefMap a = maps.at(cf, t, 4);
        int cached = maps.cachedMethods();
        assertSame("second query is served from the cache", a, maps.at(cf, t, 4));
        assertEquals(cached, maps.cachedMethods());
        assertNull("pc inside an instruction", maps.at(cf, t, 6));       // 5 is ifeq (3 bytes): 6 and 7 are operands
        assertNull(maps.at(cf, t, -1));
        assertNull(maps.at(cf, t, 10000));
        assertTrue(a.stackIsRef(0) && a.stackIsRef(1) && !a.localIsRef(0) && !a.stackIsRef(2) && !a.localIsRef(5));
        assertEquals(2, a.refCount());
        // a method that does not verify cannot be mapped
        CorpusVerifyTest.MapSource bad = new CorpusVerifyTest.MapSource();
        File f = new File(GeneratedVerifyTest.DIR, "n01_wrong_stack_type.class");
        ClassFile bcf = ClassParser.parse(Files.readAllBytes(f.toPath()));
        try {
            maps.at(bcf, bcf.findMethod("t", "()V"), 0);
            fail();
        } catch (VerifyException expected) {
        }
    }
}
